/**
 * LifeQuest Mnemonic Connection Explainer (מפענח הקשרים האסוציאטיביים וגשרי הזיכרון)
 * 
 * תפקיד: להסביר ללקוח במדויק מדוע המילה קשורה לתמונה, ולפתור את ה"חידה המוחית"
 * של הקושי הרצוי (Desirable Difficulty).
 * 
 * ברירת מחדל: מוסתר בממשק כדי לאפשר למשתמש להתאמץ מעט.
 * בלחיצה על "למה זה קשור? 💡" — חושף הסבר בהיר, קולח, הגיוני ומשכנע שנצרב בזיכרון!
 */

export function getMnemonicConnectionExplanation(
  itemTitle = '', 
  associationWord = '', 
  cardName = '', 
  imageUrl = '', 
  providedStoryOrExplanation = ''
) {
  // If a high-quality explanation was already generated by the AI / curator engine, use it!
  const customExp = String(providedStoryOrExplanation || '').trim();
  if (customExp && !customExp.includes('המוח קושר בין') && customExp.length > 10) {
    return customExp;
  }

  const item = String(itemTitle || '').trim().toLowerCase();
  const anchor = String(associationWord || cardName || '').trim().toLowerCase();
  const img = String(imageUrl || '').toLowerCase();

  // Special thematic checks for Karaoke & Military / Base tasks
  if (/קריוקי/.test(item) || /קריוקי/.test(anchor)) {
    if (/מיקרופון/.test(anchor)) {
      return 'מיקרופון הוא הלב הפועם של הקריוקי — כשמדמיינים מיקרופון נוצץ עומד בחדר, מיד שומעים את השירה ונזכרים לקחת את הקריוקי!';
    }
    if (/רמקול|מסיב/.test(anchor)) {
      return 'רמקול מסיבות מרעיד את החדר עם הבאסים של הקריוקי — עוגן שמיעתי וויזואלי שמבטיח שלא תשכח את המשימה!';
    }
    if (/כומתה|חייל|מדימ|בסיס/.test(anchor)) {
      return 'הכומתה והמדים מייצגים את הבסיס הצבאי שאליו צריך להביא את הציוד — קיבוע היעד בראש חורט את המשימה בזיכרון!';
    }
  }

  if (/בסיס|צבא|טירונות|מוצב/.test(item)) {
    if (/כומתה/.test(anchor)) {
      return 'הכומתה על הראש היא סמל השירות והמשמעת בבסיס — עוגן שמקשר מיד לכל משימה או ציוד שצריך לקחת לשם!';
    }
  }

  // 1. יד / ידיים
  if (/יד|ידיים/.test(item)) {
    if (/ספיידרמן|spider/.test(anchor) || /spider/.test(img)) {
      return 'לספיידרמן יש יד דביקה שממנה הוא יורה קורי עכביש בכל תנועת אצבעות — עוגן מושלם שמחבר כף יד לפעולה על-טבעית!';
    }
    if (/מתאגרף|איגרוף|כפפות/.test(anchor)) {
      return 'המתאגרף נלחם אך ורק בעזרת הידיים ועוטה כפפות איגרוף ענקיות וזוהרות על כל יד כדי להנחית נוק-אאוט!';
    }
    if (/לחיצת|פגישה/.test(anchor)) {
      return 'לחיצת ידיים מפגישה בין שתי כפות ידיים שנסגרות יחד בתנועת אמון והסכמה!';
    }
    return 'העוגן ממחיש פעולה פיזית מובהקת של כף היד — תנועה, אחיזה או מגע שמקבעים את המילה בזיכרון!';
  }

  // 2. בלון / בלונים
  if (/בלון|בלונים/.test(item)) {
    if (/ליצן/.test(anchor)) {
      return 'הליצן מנפח בלונים צבעוניים ומעצב מהם חיות וצורות בקרקס — קפיצה מוחית קלאסית: רואים ליצן ומיד נזכרים בבלון!';
    }
    return 'העוגן מייצג מסיבה וחגיגה צבעונית שבה מפריחים בלונים לאוויר!';
  }

  // 3. שמאל / שמאלה
  if (/שמאל|שמאלה/.test(item)) {
    if (/שוטר|תנועה/.test(anchor)) {
      return 'שוטר התנועה עומד בצומת ומכוון בידו המושטת את כל הרכבים לפנות שמאלה!';
    }
    if (/לב/.test(anchor)) {
      return 'הלב של גוף האדם פועם בצד שמאל של החזה — עוגן פנימי חזק לצד שמאל!';
    }
    return 'עוגן כיוון מובהק שממקד את תשומת הלב של המוח בפנייה שמאלה במסלול הארמון!';
  }

  // 4. פנויה / פנוי
  if (/פנויה|פנוי/.test(item)) {
    if (/מונית/.test(anchor)) {
      return 'על גג המונית הצהובה דולק שלט "פנוי" (TAXI) שמסמן שהיא פנויה לנסיעה מיידית!';
    }
    if (/כלה|רווק/.test(anchor)) {
      return 'הדמות מסמלת חופש ופניות להצעות חדשות!';
    }
    return 'החפץ או הדמות מסמלים זמינות, חופש ומקום פנוי שממתין להתמלא!';
  }

  // 5. ימין / ימינה
  if (/ימין|ימינה/.test(item)) {
    if (/חייל|מצדיע/.test(anchor)) {
      return 'החייל מצדיע למפקד ביד ימין מתוחה וגאה — סמל מובהק ובלתי נשכח לצד ימין!';
    }
    return 'עוגן כיוון מובהק המקבע את פניית הימין במסלול הזיכרון!';
  }

  // 6. קרח / שלג
  if (/קרח|שלג/.test(item)) {
    if (/אסקימואי|איגלו/.test(anchor)) {
      return 'האסקימואי בונה איגלו וחי על משטחי הקרח והשלג הלבנים בקוטב הקפוא!';
    }
    return 'עוגן סנסורי של קור עז ומשטחי שלג וקרח שמקבע את הטמפרטורה בזיכרון!';
  }

  // 7. טיפול שיניים / שיניים / רופא שיניים
  if (/שיניים|טיפול\s*שיניים|שיננית/.test(item)) {
    if (/דרקולה|ערפד/.test(anchor)) {
      return 'לדרקולה יש ניבי שיניים חדים וארוכים במיוחד שזקוקים לטיפול שיניים דחוף!';
    }
    return 'עוגן ויזואלי המדגיש שיניים בולטות, חיוך רחב או בדיקה דנטלית!';
  }

  // 8. משקפיים / משקפי ראייה
  if (/משקפיים|משקפי\s*ראייה/.test(item)) {
    if (/חנון/.test(anchor)) {
      return 'החנון מרכיב משקפי ראייה עבים במיוחד כדי לקרוא ספרים ולחקור שעות ארוכות!';
    }
    return 'עוגן חזותי המדגיש עדשות ומסגרת בולטת על הפנים!';
  }

  // 9. סתימה / אינסטלטור / ברז
  if (/סתימה|אינסטלטור|ברז|צנרת/.test(item)) {
    if (/מריו/.test(anchor)) {
      return 'סופר מריו הוא אינסטלטור מיתולוגי שמגיע עם מפתח שוודי כדי לפתוח סתימות בצנרת!';
    }
    return 'איש מקצוע מומחה שמטפל במים ובצנרת כדי לפתוח כל סתימה!';
  }

  // 10. כושר / אימון / שרירים
  if (/כושר|אימון|שרירים|משקולות/.test(item)) {
    if (/שוורצנגר/.test(anchor)) {
      return 'ארנולד שוורצנגר הוא אלוף פיתוח הגוף וסמל הכושר, המשקולות והשרירים הבינלאומי!';
    }
    return 'עוגן של מאמץ פיזי, הרמת משקולות כבדות ומשמעת ספורטיבית!';
  }

  // 11. תספורת / מספרה / ספר
  if (/תספורת|מספרה|ספר|קוצים/.test(item)) {
    if (/סוניק/.test(anchor)) {
      return 'לסוניק יש קוצים כחולים בולטים בשיער שנראים כמו תספורת קוצים מושלמת ומדויקת!';
    }
    return 'עיצוב שיער נועז ומספריים מקצועיות שנחרטים מיד בזיכרון!';
  }

  // 12. חשמל / סוללה / מטען
  if (/חשמל|סוללה|סוללות|מטען|שקע/.test(item)) {
    if (/פיקאצ/.test(anchor)) {
      return 'פיקאצ\'ו הוא פוקימון חשמלי שיורה ברקים וטוען סוללות במכת חשמל אנרגטית!';
    }
    return 'עוגן של מתח גבוה, ניצוצות כחולים וטעינת אנרגיה מיידית!';
  }

  // 13. פגישה / מפגש
  if (/פגישה|מפגש/.test(item)) {
    return 'בכל פגישה עסקית או אישית מוצלחת חותמים את המפגש בלחיצת ידיים הדדית ומחייכת!';
  }

  // 14. שיחה / טלפון
  if (/שיחה|טלפון/.test(item)) {
    return 'שיחת טלפון מחברת בין שני אנשים דרך שפופרת קולית וחיוג מספרים צלול!';
  }

  // 15. שניצל / שניצלים / אוכל
  if (/שניצל|שניצלים/.test(item)) {
    return 'שניצל פריך, חם וזהוב על הצלחת הוא סמל של ארוחה ביתית מנחמת שמעוררת תיאבון וחושים!';
  }

  // 16. סדרת אנימציה / סרט / טלוויזיה
  if (/סדרת\s*אנימציה|אנימציה|סדרה/.test(item)) {
    return 'דמויות מצוירות בסדרת אנימציה זזות, מדברות ומשמחות על המסך — עולם של יצירתיות וצבע!';
  }

  // 17. דרקון / אש
  if (/דרקון/.test(item)) {
    return 'הדרקון המיתולוגי יורק להבות אש אדירות ומגן על אוצרות הממלכה בארמון!';
  }

  // 18. לוחם / אביר / חרב
  if (/לוחם|אביר|חרב/.test(item)) {
    return 'הלוחם לבוש שריון פלדה מלא ונושא חרב ומגן כדי לצאת לקרב אמיץ!';
  }

  // 19. בובספוג / ספוג
  if (/בובספוג/.test(item)) {
    return 'בובספוג הוא ספוג צהוב תוסס ומלא חיים שחי באוקיינוס וזוכר כל פרט בהתלהבות!';
  }

  // 20. פירמידות / עבדים
  if (/פירמידות|פירמידה|מצרים/.test(item)) {
    return 'הפירמידות הענקיות במצרים נבנו מאבנים מסיביות לאורך מאות שנים ומהוות מונומנט נצחי!';
  }

  // 21. תחמושת / כדורים
  if (/תחמושת|כדורים/.test(item)) {
    return 'פגזי תותח ותרמילי תחמושת מוזהבים מוכנים לטעינה מהירה כדי להבקיע את המטרה!';
  }

  // 22. כסף / חשבון / בנק
  if (/כסף|חשבון|בנק/.test(item)) {
    return 'שק כסף מלא במטבעות זהב מצלצלים מסמל עושר, תשלום חשבונות וביטחון כלכלי!';
  }

  // 23. דוח 1 / נוכחות
  if (/דוח|נוכחות/.test(item)) {
    return 'תלמידה מצביעה בגאווה בכיתה כדי לסמן נוכחות מלאה בדוח הבוקר!';
  }

  // 24. חופשה / טיסה
  // 25. מצחיק / צחוק / הומור / בדיחה
  if (/מצחיק|צחוק|הומור|בדיחה/.test(item)) {
    if (/צפלין|צ'פלין|chaplin/.test(anchor) || /chaplin/.test(img)) {
      return "צ'רלי צ'פלין, גדול הקומיקאים של הראינוע, הצחיק מיליונים בעזרת כובע באולר, מקל הליכה ומעידות מגושמות — עוגן בלתי נשכח להומור וצחוק!";
    }
    return 'מר בין (Rowan Atkinson) הוא אמן הקומדיה העולמי — כל הבעת פנים, נפילה ושטות שלו קורעת מצחוק! כשחושבים על "מצחיק", רואים מיד את מר בין בראש!';
  }

  // 26. עצוב / בכי
  if (/עצוב|בכי|דמעות/.test(item)) {
    return 'התינוק הבוכה מזיל דמעות גדולות — סמל מובהק ואוניברסלי לעצב ובכי!';
  }

  // 27. כועס / עצבים / זעם
  if (/כועס|עצבים|זעם/.test(item)) {
    return 'הענק הירוק (האלק) מתעצבן ושובר קירות בכל פעם שהוא כועס — סמל מוחלט לזעם וכעס!';
  }

  // 28. חכם / גאון
  if (/חכם|גאון|שכל/.test(item)) {
    return 'אלברט איינשטיין מוציא לשון הוא סמל הגאונות, החוכמה והמחשבה המקורית בעולם!';
  }

  // 29. מהיר / זריז
  if (/מהיר|זריז|מהירות/.test(item)) {
    return 'רכב פורמולה 1 טס במהירות מסחררת על המסלול — סמל מובהק למהירות וזריזות!';
  }

  // 30. איטי / לאט
  if (/איטי|לאט/.test(item)) {
    return 'הצב זז לאט ובסבלנות צעד אחרי צעד — עוגן קלאסי לאיטיות, רוגע וסבלנות!';
  }

  // 31. חזק / כוח
  if (/חזק|כוח|עוצמה/.test(item)) {
    return 'ארנולד שוורצנגר מרים משקולות ברזל ענקיות בכוח שרירי אדיר — סמל הכוח האנושי!';
  }

  // 32. מפחיד / פחד
  if (/מפחיד|פחד|אימה/.test(item)) {
    return 'רוח רפאים מרחפת בטירה עתיקה היא סמל הפחד, המסתורין והאימה המובהק ביותר!';
  }

  // 33. חם / חום
  if (/^חם$|^החם$|^בחום$|חום|שרב/.test(item)) {
    return 'דיונות המדבר הלוהטות תחת שמש יוקדת ממחישות חום קיצוני וצמא עז!';
  }

  // 34. ישן / עייף
  if (/ישן|עייף|שינה/.test(item)) {
    return 'דב הפנדה מתנמנם שעות ארוכות על ענף עץ — עוגן מרגיע ומושלם לשינה ועייפות!';
  }

  // 35. נקי / ניקיון
  if (/נקי|ניקיון|לנקות/.test(item)) {
    return 'סינדרלה מקרצפת את הרצפה עם מטאטא וסבון עד שהכול נוצץ ומבריק!';
  }

  // 36. טעים / טעם
  if (/טעים|טעם/.test(item)) {
    return 'השף האיטלקי מוציא פיצה לוהטת מהתנור ומריח את הניחוח הטעים — סמל עולמי לטעם נפלא!';
  }

  // 37. דור / דורות
  if (/^דור$|דורות/.test(item)) {
    if (/אוהל|טיפי|אינדיאן|מדורה/.test(anchor) || /teepee|tent|indian|fire/.test(img)) {
      return 'שבט אינדיאנים מכונס סביב המדורה ומעביר סיפורים ומסורת מדור לדור — אש השבט מחברת את "דור" עם "מדורה"!';
    }
    if (/עץ|משפחה|סבא|שורש/.test(anchor) || /tree|family|grand/.test(img)) {
      return 'עץ משפחה מסמל סבא, הורים וילדים שמעבירים את הלפיד מדור לדור!';
    }
    return 'עוגן שמייצג שרשרת דורות, מורשת או מסורת משפחתית כדי לקבע את המילה "דור"!';
  }

  // 38. א.ש.מ (באשמתי / אשם / אשמה)
  if (/^.*אשמ.*$/.test(item)) {
    if (/prisoner|mugshot|אסיר|כלא/.test(img) || /אסיר|כלא/.test(anchor)) {
      return 'אסיר במדי כלא כתומים אוחז בשלט GUILTY ומודה בפה מלא: "באשמתי!" — עוגן מוחשי וחד-משמעי של לקיחת אחריות ועונש.';
    }
    if (/gavel|judge|פטיש|שופט|משפט/.test(img) || /פטיש|שופט|משפט/.test(anchor)) {
      return 'פטיש השופטים מכה בבית המשפט ופוסק GUILTY (אשם!) — הצליל והמראה של הכרעת הדין מקבעים את המילה "באשמתי" בזיכרון.';
    }
    if (/finger|pointing|אצבע/.test(img) || /אצבע/.test(anchor)) {
      return 'אצבע מופנית ישירות אליך ומצביעה: "זה באשמתך!" — עוגן אישי ומטלטל שנחרט בזיכרון ולא ניתן לשכוח אותו.';
    }
    return 'עוגן חזותי עוצמתי מעולם המשפט והענישה שמקבע את תחושת האשמה בזיכרון לטווח ארוך!';
  }

  // 39. לחימה / קרב
  if (/לחימה|להילחם|לוחם|קרב/.test(item)) {
    if (/combat|ring|boxing|אגרוף|זירה/.test(img) || /אגרוף|זירה/.test(anchor)) {
      return 'שני לוחמים בזירת קרב מתוחה עם כפפות אגרוף — עוגן סוער, דינמי ומוחשי לפעולת הלחימה!';
    }
    if (/sword|חרב|גלדיאטור/.test(img) || /חרב/.test(anchor)) {
      return 'חרב פלדה חדה ומגן של לוחם בשדה הקרב — עוגן פיזי חד ומובהק ללחימה!';
    }
    return 'עוגן ויזואלי של לוחם או זירת קרב שמקבע את המושג "לחימה" בעוצמה בזיכרון!';
  }

  // 40. לחם / מאפה
  if (/^לחם$|^הלחם$|^בלחם$|לחמים|חלה/.test(item)) {
    if (/bread|לחם|מאפייה/.test(img) || /לחם|מאפה/.test(anchor)) {
      return 'כיכר לחם טרייה ופריכה עם קרום שחום וסדוק שיצאה הרגע מהתנור במאפייה — עוגן חושי של ריח וטעם נפלא ללחם!';
    }
    if (/croissant|קרואסון/.test(img) || /קרואסון/.test(anchor)) {
      return 'קרואסון חמאה פריך ומאפה בצק חם מבית קפה — עוגן מאפה שמתחבר מיד ללחם!';
    }
    return 'עוגן חושי של מאפה חם וטרי שמקבע את המילה "לחם" בדמיון!';
  }

  // 41. חליל / נגינה
  if (/חליל|חלילים|חלילן/.test(item)) {
    if (/flute|חליל/.test(img) || /חליל/.test(anchor)) {
      return 'חליל צד כסוף ונוצץ עם מנגנון מפתחות מתכת שמפיק צלילים שמימיים — עוגן מוזיקלי מדויק לצליל החליל!';
    }
    return 'כלי נגינה עדין שמפיק צליל רועים קסום ומחבר את המילה "חליל" לזיכרון!';
  }

  // 42. לטייל / טיול
  if (/לטייל|טיול|מטייל|תרמילאי/.test(item)) {
    if (/hiker|trail|backpack|תרמיל|שביל/.test(img) || /תרמיל|שביל|מטייל/.test(anchor)) {
      return 'מטייל עם תרמיל גב ענק ומקל הליכה צועד בשביל הרים מול נוף ירוק — עוגן מוחשי ומושלם לפעולה "לטייל"!';
    }
    if (/compass|מצפן/.test(img) || /מצפן/.test(anchor)) {
      return 'מצפן ניווט מבריק שנפתח על גבי מפת שבילים כדי לצאת לטיול בשטח!';
    }
    return 'עוגן שטח וטבע שממחיש את פעולת הטיול והצעידה בשביל!';
  }

  // 43. לצלצל / צלצול / טלפון
  if (/לצלצל|צלצול|טלפון|חיוג/.test(item)) {
    if (/phone|telephone|rotary|טלפון|חוגה/.test(img) || /טלפון|חוגה/.test(anchor)) {
      return 'טלפון חוגה אדום עתיק שמצלצל בקול פעמונים מתכתי מהדהד — עוגן קולי וחזותי בלתי נשכח לפעולה "לצלצל"!';
    }
    return 'טלפון מצלצל שממקד את תשומת הלב של המוח בצלצול ובחיוג!';
  }

  // Fallback intelligent derivation (Concrete, sensible & memory-oriented!)
  const cleanItem = String(itemTitle || '').trim();
  const cleanAnchor = String(associationWord || cardName || '').trim();

  if (!cleanAnchor || cleanAnchor === cleanItem) {
    return `העוגן החזותי ממחיש באופן פיזי וברור את "${cleanItem}" בתוך החדר בארמון. עצום לרגע עיניים ודמיין אותו ניצב בחדר כדי לחרוט אותו בזיכרון!`;
  }

  return `העוגן "${cleanAnchor}" נבחר כדי להפוך את המשימה "${cleanItem}" לעצם מוחשי ומעורר חושים בארמון הזיכרון. המוח זוכר חפצים וסמלים חיים פי כמה מטקסט יבש — כשתיכנס לתחנה ותראה את ה-${cleanAnchor}, המשימה תקפוץ מיד לראש!`;
}

export default getMnemonicConnectionExplanation;
